#!/usr/bin/env python3
"""
Post LLM evaluation as a PR review on GitHub.

This script reads the evaluation JSON generated by grade_submission.py
and posts it as a PR review with inline comments on the student's PR.
"""

import json
import os
import sys
from pathlib import Path
from urllib.request import Request, urlopen
from urllib.error import HTTPError


def get_pr_number(repo: str, token: str) -> int | None:
    url = f"https://api.github.com/repos/{repo}/pulls?state=open&sort=created&direction=desc&per_page=1"
    req = Request(url, headers={
        "Authorization": f"token {token}",
        "Accept": "application/vnd.github.v3+json"
    })
    try:
        with urlopen(req) as response:
            pulls = json.loads(response.read())
            if pulls:
                return pulls[0]["number"]
    except HTTPError as e:
        print(f"ERROR fetching PRs: {e}", file=sys.stderr)
    return None


def format_review_body(evaluation: dict) -> str:
    lines = ["## 🤖 Avaliação Automatizada por LLM\n"]
    total = evaluation.get("total_score", "N/A")
    total_max = evaluation.get("total_max_score", 10)
    lines.append(f"**Nota total: {total}/{total_max}**\n")

    criteria = evaluation.get("criteria", [])
    if criteria:
        lines.append("### Notas por Critério")
        lines.append("| Critério | Nota | Máximo |")
        lines.append("|----------|------|--------|")
        for c in criteria:
            name = c.get("criterion_name", c.get("criterion_id", "?"))
            score = c.get("score", "?")
            max_score = c.get("max_score", 10)
            lines.append(f"| {name} | {score} | {max_score} |")
        lines.append("")

    feedback = evaluation.get("student_feedback", "")
    if feedback:
        lines.append("### Resumo do Feedback\n")
        lines.append(feedback)
        lines.append("")

    lines.append("---")
    lines.append("*Esta avaliação foi gerada automaticamente por LLM como apoio ao monitor. "
                 "A nota oficial é atribuída pelo monitor humano.*")
    return "\n".join(lines)


def build_inline_comments(evaluation: dict) -> list:
    """Extrai os evidence_refs e tenta mapear para linha do arquivo."""
    comments = []
    items = evaluation.get("feedback_items", [])
    
    # Agrupa por (path, line) para evitar erro caso dois feedbacks fiquem na mesma linha
    grouped_comments = {}
    
    for item in items:
        problem = item.get("problem", "")
        how_to_fix = item.get("how_to_fix", "")
        refs = item.get("evidence_refs", [])
        if not refs:
            continue
            
        body = f"**Problema:** {problem}\n\n💡 **Como consertar:** {how_to_fix}"
        
        for ref in refs:
            # Pula refs que não parecem ser paths
            if ref.startswith("model_output:") or not "/" in ref:
                continue
                
            parts = str(ref).split("#")
            path = parts[0]
            target = parts[1] if len(parts) > 1 else ""
            
            line_val = 1
            if os.path.exists(path):
                if target:
                    try:
                        with open(path, "r", encoding="utf-8") as f:
                            lines = f.readlines()
                            for i, l in enumerate(lines):
                                if target in l:
                                    line_val = i + 1
                                    break
                    except Exception:
                        pass
                
                key = (path, line_val)
                if key not in grouped_comments:
                    grouped_comments[key] = []
                grouped_comments[key].append(body)

    for (path, line), bodies in grouped_comments.items():
        comments.append({
            "path": path,
            "line": line,
            "body": "\n\n---\n\n".join(bodies)
        })
        
    return comments


def post_review(repo: str, pr_number: int, body: str, inline_comments: list, token: str):
    url = f"https://api.github.com/repos/{repo}/pulls/{pr_number}/reviews"
    
    headers = {
        "Authorization": f"token {token}",
        "Accept": "application/vnd.github.v3+json",
        "Content-Type": "application/json"
    }
    
    # Tenta postar COM os comentários inline primeiro
    payload_with_comments = {
        "body": body,
        "event": "COMMENT",
        "comments": inline_comments
    }
    
    try:
        req = Request(url, data=json.dumps(payload_with_comments).encode("utf-8"), method="POST", headers=headers)
        with urlopen(req) as response:
            result = json.loads(response.read())
            print(f"Review posted DO COM comentários inline: {result.get('html_url', '')}")
            return
    except HTTPError as e:
        error_msg = e.read().decode("utf-8", errors="replace")
        if e.code == 422:
            print(f"Aviso: Não foi possível postar comentários inline (422). Algum arquivo/linha do evidence_refs pode não fazer parte do Diff do PR: {error_msg}")
            print("Fazendo fallback para review em texto puro sem comentários inline...")
        else:
            print(f"ERROR: Fallback ocorreu. details: {error_msg}")

    # Fallback: se falhar (ex: path não existe no PR diff, ou 422), posta só o body principal + anexar os itens no body
    # Recriaremos o texto antigo para garantir que os itens não se perderam
    evaluation = json.loads(Path("evaluation.json").read_text(encoding="utf-8"))
    
    lines = [body]
    items = evaluation.get("feedback_items", [])
    if items:
        lines.insert(-2, "### Pontos de Atenção\n") # Inserir antes da Assinatura
        for i, item in enumerate(items, 1):
            problem = item.get("problem", "")
            how_to_fix = item.get("how_to_fix", "")
            refs = ", ".join(item.get("evidence_refs", []))
            lines.insert(-2, f"**{i}.** {problem}")
            if how_to_fix:
                lines.insert(-2, f"   - 💡 *Como consertar:* {how_to_fix}")
            if refs:
                lines.insert(-2, f"   - 📍 *Referência:* `{refs}`")
            lines.insert(-2, "")
            
    payload_fallback = {
        "body": "\n".join(lines),
        "event": "COMMENT"
    }

    try:
        req = Request(url, data=json.dumps(payload_fallback).encode("utf-8"), method="POST", headers=headers)
        with urlopen(req) as response:
            result = json.loads(response.read())
            print(f"Review posted successfully sem inline comments: {result.get('html_url', '')}")
    except HTTPError as e:
        print(f"ERROR posting review mesmo no Fallback: {e.code} - {e.read().decode('utf-8')}", file=sys.stderr)
        sys.exit(1)


def main():
    token = os.environ.get("GITHUB_TOKEN", "")
    repo = os.environ.get("GITHUB_REPOSITORY", "")

    if not token or not repo:
        print("ERROR: GITHUB_TOKEN ou GITHUB_REPOSITORY ausente", file=sys.stderr)
        sys.exit(1)

    eval_path = Path("evaluation.json")
    if not eval_path.exists():
        print("ERROR: evaluation.json not found.", file=sys.stderr)
        sys.exit(1)

    evaluation = json.loads(eval_path.read_text(encoding="utf-8"))
    
    pr_number = get_pr_number(repo, token)
    if pr_number is None:
        print("WARNING: No open PR found. Skipping review.", file=sys.stderr)
        return

    body = format_review_body(evaluation)
    inline_comments = build_inline_comments(evaluation)
    
    post_review(repo, pr_number, body, inline_comments, token)

if __name__ == "__main__":
    main()
